package com.airpointer.remote

import android.annotation.SuppressLint
import android.content.Context
import org.json.JSONArray

/**
 * Line icons for shortcut buttons: the full Lucide set (https://lucide.dev, ISC license, v1.48.0) as
 * res/drawable/lic_<name>.xml, plus AirPointer's own play-pause. Generated by android/tools/lucide_convert.py,
 * which also writes assets/lucide-icons.json (names and search tags). Looked up by name at runtime: a
 * compiled-in map of 2000+ icons would be too large for one method.
 */
object Icons {
    class Info(val name: String, val tags: List<String>)

    private val extra = linkedMapOf("play-pause" to R.drawable.ic_play_pause)
    private val cache = HashMap<String, Int>()
    @Volatile private var all: List<Info>? = null

    /** Drawable id of the icon called [name], or null if there's no such icon. */
    @SuppressLint("DiscouragedApi")
    fun of(context: Context, name: String?): Int? {
        if (name.isNullOrEmpty()) return null
        extra[name]?.let { return it }
        synchronized(cache) {
            val id = cache.getOrPut(name) {
                context.resources.getIdentifier("lic_" + name.replace('-', '_'), "drawable", context.packageName)
            }
            return id.takeIf { it != 0 }
        }
    }

    /** Every icon, in name order (play-pause first). */
    fun all(context: Context): List<Info> {
        all?.let { return it }
        val json = context.assets.open("lucide-icons.json").bufferedReader().use { it.readText() }
        val a = JSONArray(json)
        val list = ArrayList<Info>(a.length() + extra.size)
        extra.keys.forEach { list.add(Info(it, listOf("media", "music", "play", "pause"))) }
        for (i in 0 until a.length()) {
            val e = a.getJSONArray(i)
            val t = e.getJSONArray(1)
            list.add(Info(e.getString(0), List(t.length()) { t.getString(it) }))
        }
        return list.also { all = it }
    }

    /** Icons whose name or tags contain every word of [query]. */
    fun search(context: Context, query: String): List<Info> {
        val words = query.lowercase().split(' ', '-').filter { it.isNotBlank() }
        if (words.isEmpty()) return all(context)
        return all(context).filter { info -> words.all { w -> info.name.contains(w) || info.tags.any { it.contains(w) } } }
    }
}
